def conjugate {G : Type*} [Group G] (x : G) (H : Subgroup G) : Subgroup G where
  carrier := {a : G | ∃ h, h ∈ H ∧ a = x * h * x⁻¹}
  inferInstance

#align simpa_comap_of_le (since := "2024-10-05")}

theorem t1 (φ : G →* H) (S T : Subgroup H) (hST : S ≤ T) : comap φ S ≤ comap φ T :=
  (comap φ). order_le _ _ hST

theorem t2 (φ : G →* H) (S T : Subgroup G) (hST : S ≤ T) : map φ S ≤ map φ T :=
  SetLike.map_le (OrderHom.map_le S ≤ map_le OrderHom.map_le T) hST <| by intro x hx;
  simp [mem_map] at *

theorem t4 (φ : G →* H) (ψ : H →* K) (S : Subgroup G) :
    map (ψ.comp φ) S = map ψ (S.map φ) := by
  rw [Stab}

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K) <;>
  Nat.bij_card _ _ h'

#align fintype_quotientiso fintype_quotientiso

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K) <;> simp [h, h']

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K)
  ((QuotientGroup.mk' H).ker_restrict K h ▸ by simp [h]) h'

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K) <|
    Nat.bijective_iff_injective_and_card (h'.symm.ltComm_le_nonempty h.notempty).1 $ by simp [h]

def iso₁ [Fintype G] (h : Disjoint H K) (h' : Nat.card G = Nat.card H * Nat.card K) : K ≃* G ⧸ H :=
  MulEquiv.ofBijective ((QuotientGroup.mk' H).restrict K)
  (Nat.bijective_iff_injective_and_card.basis h' <| by simp [h])
